const menu=document.querySelector('.menu'),nav=document.querySelector('#nav'),cursor=document.querySelector('.cursor');
if(menu){menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.textContent=open?'Close':'Index';nav.classList.toggle('open',open);nav.setAttribute('aria-hidden',String(!open))};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Index'}))}
addEventListener('pointermove',e=>{if(cursor){cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px'}});document.querySelectorAll('a,button,.image-wrap').forEach(el=>{el.addEventListener('mouseenter',()=>cursor?.classList.add('big'));el.addEventListener('mouseleave',()=>cursor?.classList.remove('big'))});
document.querySelectorAll('.transition-link').forEach(a=>a.addEventListener('click',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;e.preventDefault();document.querySelector('.wipe').classList.add('in');setTimeout(()=>location.href=a.href,610)}));
const result=document.querySelector('#filter-result');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');result.textContent=`${b.textContent} shapes the reading of all four studies.`});
const reveal=()=>document.querySelectorAll('.image-wrap').forEach(el=>{const r=el.getBoundingClientRect(),p=Math.max(0,Math.min(1,1-(r.top-innerHeight*.82)/innerHeight));el.style.clipPath=`inset(${(1-p)*18}% 0 0)`});addEventListener('scroll',reveal,{passive:true});reveal();
